//! Protocol translation between a Minecraft client and a backend server that
//! speak different protocol versions, from 1.12 to 26.3.
//!
//! A [`Translator`] chains steps between adjacent protocol versions. Each
//! step converts packets in both directions for one pair of versions: either
//! for a newer client on an older backend (`up`) or for an older client on a
//! newer backend (`down`). The crate does no I/O: the caller feeds it packets
//! and sends on what it returns.
//!
//! Per-version packet tables, registries and block states under `data/` are
//! generated by `scripts/translation_data.py` from Mojang's own data reports
//! and the MIT-licensed PrismarineJS minecraft-data. Packets a step does not
//! change pass through untouched; a packet a step must change but cannot
//! parse fails the connection rather than reaching the peer corrupted.
pub mod codec;
pub mod data;
pub mod mapping;
pub mod nbt;
pub mod step;
pub mod steps;
mod translator;
pub mod version;
pub mod wire;

pub use translator::{Output, Sent, Translator, supported};

/// One packet: its ID and the body that follows it.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Packet {
    pub id: i32,
    pub data: Vec<u8>,
}

impl Packet {
    pub fn new(id: i32, data: Vec<u8>) -> Self {
        Self { id, data }
    }

    pub fn empty(id: i32) -> Self {
        Self::new(id, Vec::new())
    }
}

/// A protocol phase. Translation starts in `Login`; the caller handles the
/// handshake and status itself.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum State {
    Handshake,
    Status,
    Login,
    Configuration,
    Play,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum Direction {
    Serverbound,
    Clientbound,
}
